from pathlib import Path
from docx import Document
from docx.shared import Inches, Pt, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT, WD_CELL_VERTICAL_ALIGNMENT
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

OUT=Path('output/docx/ConstComp Dashboard Docs - Relasi Data Lengkap.docx'); OUT.parent.mkdir(parents=True,exist_ok=True)
BLUE='2E74B5'; DARK='1F4D78'; LIGHT='E8EEF5'; GRAY='F2F4F7'
doc=Document(); sec=doc.sections[0]
sec.top_margin=sec.bottom_margin=Inches(1); sec.left_margin=sec.right_margin=Inches(1); sec.header_distance=sec.footer_distance=Inches(.492)

normal=doc.styles['Normal']; normal.font.name='Calibri'; normal._element.rPr.rFonts.set(qn('w:eastAsia'),'Calibri'); normal.font.size=Pt(11); normal.paragraph_format.space_after=Pt(6); normal.paragraph_format.line_spacing=1.10
for name,size,color,before,after in [('Heading 1',16,BLUE,16,8),('Heading 2',13,BLUE,12,6),('Heading 3',12,DARK,8,4)]:
 s=doc.styles[name]; s.font.name='Calibri'; s.font.size=Pt(size); s.font.bold=True; s.font.color.rgb=RGBColor.from_string(color); s.paragraph_format.space_before=Pt(before); s.paragraph_format.space_after=Pt(after)

header=sec.header.paragraphs[0]; header.text='ConsComp Dashboard | Dokumentasi Sistem'; header.style='Normal'; header.runs[0].font.size=Pt(8); header.runs[0].font.color.rgb=RGBColor(100,100,100)
footer=sec.footer.paragraphs[0]; footer.alignment=WD_ALIGN_PARAGRAPH.RIGHT; r=footer.add_run('ConsComp Dashboard'); r.font.size=Pt(8); r.font.color.rgb=RGBColor(100,100,100)

def shade(cell, fill):
 tcPr=cell._tc.get_or_add_tcPr(); shd=OxmlElement('w:shd'); shd.set(qn('w:fill'),fill); tcPr.append(shd)
def set_cell(cell, text, bold=False, white=False):
 cell.text=''; p=cell.paragraphs[0]; p.paragraph_format.space_after=Pt(0); r=p.add_run(str(text)); r.bold=bold; r.font.size=Pt(8.5); r.font.name='Calibri'; r._element.rPr.rFonts.set(qn('w:eastAsia'),'Calibri');
 if white:r.font.color.rgb=RGBColor(255,255,255)
 cell.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.TOP
def table(headers, rows, widths):
 t=doc.add_table(rows=1, cols=len(headers)); t.style='Table Grid'; t.alignment=WD_TABLE_ALIGNMENT.LEFT; t.autofit=False
 for i,h in enumerate(headers): set_cell(t.rows[0].cells[i],h,True,True); shade(t.rows[0].cells[i],DARK); t.rows[0].cells[i].width=Inches(widths[i])
 for n,row in enumerate(rows):
  cells=t.add_row().cells
  for i,v in enumerate(row): set_cell(cells[i],v); cells[i].width=Inches(widths[i]);
  if n%2: [shade(c,GRAY) for c in cells]
 for row in t.rows:
  for cell in row.cells:
   tcPr=cell._tc.get_or_add_tcPr(); mar=OxmlElement('w:tcMar')
   for side in ['top','start','bottom','end']:
    e=OxmlElement(f'w:{side}'); e.set(qn('w:w'),'80' if side in ['top','bottom'] else '120'); e.set(qn('w:type'),'dxa'); mar.append(e)
   tcPr.append(mar)
 return t
def para(text,style=None): return doc.add_paragraph(text,style)

p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.space_before=Pt(160); r=p.add_run('Dokumentasi Sistem'); r.bold=True; r.font.name='Calibri'; r.font.size=Pt(26); r.font.color.rgb=RGBColor.from_string(DARK)
p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.space_after=Pt(20); r=p.add_run('ConsComp Dashboard'); r.bold=True; r.font.size=Pt(22); r.font.color.rgb=RGBColor.from_string(DARK)
p=doc.add_paragraph('Versi lengkap - bagian placeholder telah diisi berdasarkan source code proyek.'); p.alignment=WD_ALIGN_PARAGRAPH.CENTER
doc.add_page_break()

para('Daftar Isi','Heading 1'); para('1. Pendahuluan\n2. Deskripsi Sistem\n3. Kebutuhan Sistem\n4. Perancangan Sistem\n5. Panduan Sistem\n6. Testing dan Validasi')
para('Bab 1. Pendahuluan','Heading 1'); para('Sistem Dashboard Kelola Karyawan adalah aplikasi web PHP dan MySQL untuk mengelola identitas karyawan, struktur organisasi, penilaian performa, upah, lembur, izin, cuti, dokumen, ekspor data, serta audit aktivitas. Akses dibatasi menurut role dan, bagi role operasional, menurut departemen.')
para('Tujuan Sistem','Heading 2'); para('Sistem menyediakan satu sumber data utama untuk administrasi SDM, mempercepat pencarian dan pembaruan informasi, mendukung proses persetujuan operasional, serta menjaga akuntabilitas melalui login, otorisasi, dan audit aktivitas.')
para('Ruang Lingkup','Heading 2'); para('Cakupan meliputi halaman publik, login/logout, dashboard internal, data dan profil karyawan, master data, pengupahan dan slip gaji, lembur, izin/cuti, performa, analisis, pengguna, audit, personalisasi tampilan, impor, ekspor, sinkronisasi CSV, serta dokumen PDF.')

para('Bab 2. Deskripsi Sistem','Heading 1'); para('Arsitektur aplikasi menggunakan browser sebagai antarmuka, PHP sebagai pemroses permintaan dan logika bisnis, MySQL sebagai sumber data utama, serta penyimpanan berkas untuk media, hasil ekspor, dan dokumen. Chart.js digunakan untuk grafik, Dompdf untuk dokumen PDF, dan ZipArchive untuk ekspor XLSX.')
para('Fungsi Sistem','Heading 2'); table(['No.','Fungsi','Ringkasan'], [('1','Autentikasi','Login, logout, session, pembatasan role dan departemen.'),('2','Data karyawan','CRUD karyawan, media, riwayat, promosi, dan performa.'),('3','Operasional','Lembur, izin, cuti, pengganti, notifikasi, dan persetujuan.'),('4','Pengupahan','Profil gaji, komponen, pendapatan, potongan, dan slip gaji.'),('5','Administrasi','Master data, pengguna, audit, personalisasi, impor/ekspor.')],[.4,1.8,4.3])
para('Batasan Sistem','Heading 2'); para('Belum ada integrasi fingerprint, aplikasi mobile, webhook, SSO, email, atau layanan eksternal. CSV berfungsi sebagai mirror; perubahan utama dilakukan melalui aplikasi dan tersimpan di MySQL. Perhitungan PPh 21 belum tersedia.')

para('Bab 3. Kebutuhan Sistem','Heading 1'); para('Kebutuhan fungsional mencakup autentikasi, dashboard statistik, pencarian dan pagination, pengelolaan karyawan, master data, lembur, izin, cuti, upah, slip gaji, impor/ekspor, dan audit. Kebutuhan nonfungsional mencakup session aman, verifikasi password dan status akun, otorisasi role/departemen, prepared statement, NIK unik, transaksi pada proses penting, serta kompatibilitas browser modern.')
para('Ketergantungan Komponen','Heading 2'); table(['Komponen','Peran','Dampak bila tidak tersedia'], [('MySQL/mysqli','Data utama aplikasi','Login dan modul data tidak berjalan.'),('PHP dan Apache/Laragon','Menjalankan halaman dan logika','Aplikasi tidak dapat diproses.'),('Composer/Dompdf','Dokumen PDF','Slip gaji atau CV PDF gagal dibuat.'),('ZipArchive','Ekspor XLSX','Berkas Excel tidak dapat dibuat.'),('Chart.js CDN','Visualisasi grafik','Data tersedia, grafik dapat gagal dimuat.')],[1.2,2.2,3.1])

para('Bab 4. Perancangan Sistem','Heading 1'); para('4.1 Gambaran Umum Arsitektur','Heading 2'); para('Pengguna mengakses halaman publik atau dashboard melalui browser. Permintaan menuju halaman PHP pada folder Dashboard. Untuk halaman internal, auth.php memeriksa session, role, dan department_id. Jika lolos, modul menjalankan query MySQL melalui mysqli, melakukan validasi formulir, menyimpan perubahan, kemudian mencatat aktivitas yang relevan. Hasil dapat ditampilkan sebagai halaman HTML, berkas XLSX, CSV, atau PDF.')
para('4.2 Pengelolaan dan Relasi Data','Heading 2'); para('Daftar berikut memuat seluruh tabel yang terdeteksi dari source code proyek. Relasi berlabel “FK eksplisit” berasal dari CREATE TABLE. Relasi “dirujuk query” teridentifikasi dari INSERT, SELECT, atau JOIN; struktur dan foreign key-nya tetap perlu dikonfirmasi pada database aktif.')
table(['Tabel','Kolom kunci terdeteksi','Relasi / peran'], [('users','id, username, password, nama, role, department_id','Akun pengguna. department_id dirujuk ke master_departemen; menjadi pembuat, penilai, pemroses, atau approver pada tabel lain.'),('karyawan','id, emp_id, nik, employee_name, position, department_id','Entitas pusat karyawan. Dirujuk oleh absensi, upah, riwayat, performa, lembur, izin, cuti, denda, dan slip.'),('master_departemen','id, nama, is_active','Referensi departemen. FK eksplisit dari master_posisi_departemen, izin, dan cuti; juga dirujuk users/karyawan pada query.'),('master_posisi','id, nama','Referensi posisi. FK eksplisit dari master_posisi_departemen dan histori jabatan.'),('master_posisi_departemen','posisi_id, department_id','Tabel penghubung posisi-departemen. FK eksplisit ke master_posisi dan master_departemen.'),('master_status_kerja','id, nama','Master status kerja; nilai digunakan oleh data karyawan.'),('master_agama','id, nama','Master agama; nilai digunakan oleh data karyawan.'),('profil_gaji','id, karyawan_id, gaji_pokok, uang_makan','Profil upah per karyawan; dirujuk oleh komponen_gaji_karyawan.'),('jenis_komponen_gaji','id, kode, nama, kategori, metode','Master komponen gaji; dirujuk oleh komponen_gaji_karyawan.'),('komponen_gaji_karyawan','profil_gaji_id, jenis_komponen_id, nilai','Komponen per profil gaji; relasi ke profil_gaji dan jenis_komponen_gaji terdeteksi pada query.'),('pendapatan_tambahan_karyawan','id, karyawan_id, nama, nilai','Pendapatan tambahan per karyawan; dibaca saat ekspor dan pembuatan slip.'),('potongan_karyawan','id, karyawan_id, nama, nilai','Potongan per karyawan; dapat menerima hasil denda yang disetujui.'),('periode_gaji','id, tahun, bulan','Periode penggajian; FK eksplisit dari slip_gaji.'),('slip_gaji','id, periode_gaji_id, karyawan_id, generated_by, versi','FK eksplisit ke periode_gaji, karyawan, dan users.'),('slip_gaji_items','id, slip_gaji_id, kategori, kode, nama, jumlah','Rincian slip; FK eksplisit ke slip_gaji.'),('slip_gaji_batch_item','karyawan_id, batch_id','Item batch slip; penggunaan karyawan terdeteksi pada query, definisi lengkap perlu verifikasi.'),('overtime_reports','id, karyawan_id, department_id, status','Laporan lembur; dirujuk oleh overtime_approvals, overtime_compensations, ekspor, dan slip.'),('overtime_approvals','overtime_id, approver_user_id, tahap, status','Tahapan persetujuan lembur; relasi ke overtime_reports dan users terdeteksi pada query.'),('overtime_compensations','overtime_id, jumlah_upah, dimasukkan_oleh_pic','Kompensasi lembur; relasi ke laporan lembur dan users terdeteksi pada query.'),('izin_meninggalkan_pekerjaan','id, karyawan_id, department_id, karyawan_pengganti_id','FK eksplisit ke karyawan (pemohon/pengganti), master_departemen, dan users (pembuat/pemroses).'),('izin_cuti','id, karyawan_id, department_id, karyawan_pengganti_id','FK eksplisit ke karyawan (pemohon/pengganti), master_departemen, dan users (pembuat/pemroses).'),('izin_cuti_khusus','id, karyawan_id, department_id, karyawan_pengganti_id','FK eksplisit ke karyawan dan users; department_id digunakan untuk pembatasan data.'),('izin_sakit','id, karyawan_id, department_id, karyawan_pengganti_id','FK eksplisit ke karyawan (pemohon/pengganti) dan users (pembuat/pemroses).'),('absensi_karyawan','id, karyawan_id, diimpor_oleh, jam_fingerprint_masuk','FK eksplisit ke karyawan dan users pengimpor.'),('denda_reports','id, karyawan_id, department_id, dibuat_oleh_user_id, potongan_id','FK eksplisit ke karyawan dan users pembuat; potongan_id dirujuk ke potongan_karyawan saat denda disetujui.'),('denda_approvals','id, denda_id, approver_user_id, tahap, status','FK eksplisit ke denda_reports dan users.'),('penilaian_performa_karyawan','id, karyawan_id, dinilai_oleh, nilai','FK eksplisit ke karyawan dan users penilai.'),('riwayat_pendidikan','id, karyawan_id, institusi, jenjang','Riwayat pendidikan per karyawan; relasi terdeteksi dari query.'),('riwayat_pekerjaan','id, karyawan_id, nama_perusahaan, posisi','Riwayat pekerjaan per karyawan; relasi terdeteksi dari query.'),('histori_jabatan_karyawan','id, karyawan_id, department_lama_id, department_baru_id','FK eksplisit ke karyawan, master_departemen, master_posisi, dan users pengubah.'),('audit_aktivitas','id, user_id, aktivitas, dibuat_pada','Mencatat aktivitas; users dirujuk untuk nama pelaku pada query.'),('pengaturan_publik','id, nama_situs, konfigurasi tampilan','Konfigurasi tunggal halaman publik; tidak memiliki relasi data utama.')],[1.55,2.25,2.7])

para('4.3 Perancangan Komponen Aplikasi','Heading 2'); table(['Modul','Komponen utama','Fungsi'], [('Antarmuka','Browser, HTML, CSS, JavaScript','Menyajikan halaman dan menerima input.'),('Halaman aplikasi','index.php, Dashboard/*.php','Memproses permintaan dan menampilkan data.'),('Keamanan','auth.php, session, CSRF','Login, role, cakupan departemen, validasi formulir.'),('Karyawan','karyawan, profil, tambah/edit/hapus','Mengelola data, media, riwayat, promosi, performa.'),('Operasional','lembur, izin, cuti, notifikasi','Pengajuan dan persetujuan kegiatan.'),('Pengupahan','upah, slip, batch slip','Komponen gaji dan pembuatan slip.'),('Administrasi','master data, pengguna, audit','Referensi sistem dan pengawasan.'),('Pertukaran data','impor, ekspor, sinkronisasi','XLSX dan CSV mirror.')],[1.2,2.6,2.7])
para('4.4 Hak Akses Pengguna','Heading 2'); table(['Role','Hak akses utama','Batasan'], [('superadmin','Seluruh modul, pengguna, master data, audit, impor.','Tidak mengubah atau menghapus akun superadmin dari daftar pengguna.'),('admin','Dashboard, karyawan, upah, slip, lembur, izin, cuti, ekspor.','Tidak mengelola pengguna, master data, audit, personalisasi, impor.'),('direktur / manager','Dashboard, analisis dan operasional departemen.','Data dibatasi departemen; tidak CRUD karyawan.'),('koordinator','Data dan persetujuan operasional departemen.','Tidak mengelola administrasi sistem.'),('PIC','Lembur, izin, cuti, notifikasi, ekspor terkait.','Tidak membuka dashboard, data karyawan, upah, administrasi.')],[1.2,3.1,2.2])
para('4.5 Use Case dan Skenario Aktor','Heading 2'); para('Semua proses internal dimulai dengan login. Sistem memeriksa session, role, dan department_id sebelum mengizinkan halaman atau query data. PIC membuat pengajuan; koordinator dan manager/direktur memproses tahapan persetujuan sesuai status. Superadmin dapat melakukan keputusan langsung pada fungsi administratif tertentu.')

para('Bab 5. Panduan Sistem','Heading 1'); para('5.1 Panduan Umum','Heading 2'); table(['Fitur','Langkah penggunaan'], [('Halaman publik','Buka halaman utama, gunakan pencarian atau filter departemen, kemudian pilih profil karyawan yang tersedia untuk publik.'),('Login dashboard','Klik Admin, masukkan username dan password, lalu klik Masuk ke Dashboard. Sistem mengarahkan pengguna sesuai role.'),('Logout','Klik tombol Logout pada panel pengguna. Session dihentikan dan pengguna diarahkan ke login.'),('Ekspor data','Buka modul yang menyediakan ekspor, terapkan filter bila perlu, klik Ekspor, lalu simpan XLSX yang dibuat sistem.'),('Tema','Klik tombol tema di kanan atas untuk berpindah antara mode terang dan gelap.')],[1.5,5.0])
para('5.2 Pengguna sebagai Superadmin','Heading 2'); para('Superadmin menggunakan menu dashboard untuk melihat ringkasan jumlah karyawan, departemen, performa, dan grafik. Dari sidebar, superadmin dapat mengelola data karyawan, master data, pengguna, pengaturan publik, audit aktivitas, upah, slip gaji, lembur, izin, cuti, analisis, impor, serta ekspor.')
table(['Halaman','Langkah utama','Hasil'], [('Dashboard','Buka Dashboard dan pilih rentang/filter yang tersedia.','Statistik dan grafik ringkas tampil.'),('Data karyawan','Pilih Data Karyawan; gunakan Tambah/Edit/Hapus sesuai kewenangan.','Data dan riwayat karyawan tersimpan.'),('Master Data','Kelola departemen, posisi, relasi posisi-departemen, status kerja, dan agama.','Referensi tersedia pada formulir terkait.'),('Pengguna','Tambahkan atau ubah username, nama, role, dan departemen pengguna.','Akun memiliki cakupan akses yang sesuai.'),('Upah & Slip Gaji','Buka Upah, tetapkan profil/komponen; buat slip individu atau batch.','Rincian pengupahan dan PDF slip dapat dibuat.'),('Lembur, Izin & Cuti','Buka modul terkait, tinjau data, lalu proses status sesuai wewenang.','Status pengajuan dan approval diperbarui.'),('Audit Aktivitas','Buka Audit Aktivitas dan gunakan filter/pencarian jika tersedia.','Jejak tindakan pengguna dapat ditinjau.')],[1.4,3.4,1.7])

para('Bab 6. Testing dan Validasi','Heading 1'); para('Pengujian dilakukan per halaman, fungsi, akses, dan konfigurasi. Setiap hasil aktual perlu diisi setelah aplikasi dijalankan pada lingkungan yang memiliki database uji. Kolom hasil yang diharapkan berikut menjadi kriteria validasi.')
table(['ID','Tahapan pengujian','Hasil yang diharapkan'], [('TST-01','Login dengan username/password benar dan akun aktif.','Masuk ke halaman sesuai role dan session terbentuk.'),('TST-02','Login dengan password salah atau akun tidak aktif.','Akses ditolak dan pesan kesalahan tampil.'),('TST-03','Akses halaman internal tanpa login.','Pengguna dialihkan/ditolak oleh autentikasi.'),('TST-04','Role terbatas membuka halaman admin atau master data.','Akses ditolak sesuai wajibRole().'),('TST-05','Role operasional membuka data departemen lain.','Hanya data departemen sendiri yang tampil.'),('TST-06','Tambah/edit data karyawan dengan NIK yang sama.','Duplikasi NIK ditolak; data valid tersimpan.'),('TST-07','Buat lembur lalu lakukan approval berurutan.','Tahap dan status berubah sesuai role persetuju.'),('TST-08','Ajukan izin/cuti dengan karyawan pengganti.','Pengajuan tersimpan dan status dapat ditinjau.'),('TST-09','Simpan profil upah dan generate slip gaji.','Komponen konsisten dan slip dapat dibuat.'),('TST-10','Ekspor data dari modul yang diizinkan.','Berkas XLSX sesuai cakupan pengguna.'),('TST-11','Logout lalu buka ulang halaman internal.','Session berakhir dan halaman tidak dapat diakses.'),('TST-12','Uji PHP, MySQL, mysqli, ZipArchive, Composer/Dompdf.','Aplikasi, ekspor, dan PDF berjalan tanpa error.')],[.6,3.7,2.2])
